begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af600000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','records-owner@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bf600000-0000-4000-8000-000000000001','Revisão fictício','revision-synthetic','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cf600000-0000-4000-8000-000000000001','bf600000-0000-4000-8000-000000000001','Sede Revisão','sede','headquarters'),('cf600000-0000-4000-8000-000000000002','bf600000-0000-4000-8000-000000000001','Campus Revisão','campus','campus');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bf600000-0000-4000-8000-000000000001','af600000-0000-4000-8000-000000000001','owner','active','cf600000-0000-4000-8000-000000000001');
select set_config('f4.org','bf600000-0000-4000-8000-000000000001',true);select set_config('f4.unit','cf600000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"af600000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'catalog','{"id":"df600000-0000-4000-8000-000000000001","kind":"account","name":"Banco Revisão"}');
select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'catalog','{"id":"df600000-0000-4000-8000-000000000002","kind":"category","name":"Doações Revisão","direction":"income"}');
select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'entry',jsonb_build_object('id','ab600000-0000-4000-8000-000000000001','kind','income','amountCents','1000','description','Previsão inicial fictícia','account','df600000-0000-4000-8000-000000000001','category','df600000-0000-4000-8000-000000000002','competence',current_date,'due',current_date,'method','pix'));
reset role;

-- All fixtures are fictitious and rolled back; no provider calls.
create function pg_temp.revision_payload(p_id uuid,p_req uuid,p_changes jsonb default '{}') returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('id',p_req,'title',e.id,'version',e.version,'kind',e.kind,'amountCents',e.amount_cents::text,'description',e.description,'account',e.account_id,'destination',coalesce(e.destination_id::text,''),'category',coalesce(e.category_id::text,''),'center',coalesce(e.center_id::text,''),'supplier',coalesce(e.supplier_id::text,''),'person',coalesce(e.person_id::text,''),'party',e.party_name,'method',e.method,'notes',e.notes,'competence',e.competence_date,'due',e.due_date,'paid',coalesce(e.paid_date::text,''),'reason','Correção fictícia')||p_changes from private.finance_entries e where e.id=p_id
$$;
select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'catalog','{"id":"df600000-0000-4000-8000-000000000003","kind":"category","name":"Taxas fictícias","direction":"expense"}');
select set_config('revision.first',pg_temp.revision_payload('ab600000-0000-4000-8000-000000000001','ab610000-0000-4000-8000-000000000001',jsonb_build_object('paid',current_date,'amountCents','2500'))::text,true);
set local role authenticated;
select lives_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.first')::jsonb)$$,'previsão passa a recebida');
select lives_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.first')::jsonb)$$,'repetição não duplica contabilização');
select throws_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.first')::jsonb||'{"id":"ab610000-0000-4000-8000-000000000099"}')$$,'40001',null,'versão antiga recusada');
reset role;
select is((select status from private.finance_entries where id='ab600000-0000-4000-8000-000000000001'),'posted','realizado salvo');
select is((select version from private.finance_entries where id='ab600000-0000-4000-8000-000000000001'),2,'replay preserva versão');
select is((select number::text from private.finance_record_numbers where entry_id='ab600000-0000-4000-8000-000000000001'),'1','código preservado');
select set_config('revision.next',pg_temp.revision_payload('ab600000-0000-4000-8000-000000000001','ab610000-0000-4000-8000-000000000002','{"paid":"","amountCents":"3000","description":"Recebimento corrigido","party":"Pessoa sem cadastro"}')::text,true);
set local role authenticated;
select lives_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.next')::jsonb)$$,'recebido pode voltar a aberto com novos dados');
reset role;
select is((select status from private.finance_entries where id='ab600000-0000-4000-8000-000000000001'),'pending','retornou a previsão');
select is((select sum(l.delta_cents)::text from public.church_ledger_lines l join private.finance_account_links a on a.ledger_id=l.account_id where a.catalog_id='df600000-0000-4000-8000-000000000001'),'0','desmarcar zera movimento líquido sem apagar diário');
select is((select party_name from private.finance_entries where id='ab600000-0000-4000-8000-000000000001'),'Pessoa sem cadastro','nome livre alterado');
select public.finance_f2(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'settle',jsonb_build_object('id','ab620000-0000-4000-8000-000000000001','title','ab600000-0000-4000-8000-000000000001','version',3,'reason','Baixa fictícia','date',current_date,'principal','3000','interest','100','fine','50','discount','25','fee','80','feeCategory','df600000-0000-4000-8000-000000000003','account','df600000-0000-4000-8000-000000000001','method','pix'));
select set_config('revision.settled',pg_temp.revision_payload('ab600000-0000-4000-8000-000000000001','ab610000-0000-4000-8000-000000000003',jsonb_build_object('paid',current_date,'amountCents','4000','description','Título liquidado corrigido'))::text,true);
set local role authenticated;
select lives_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.settled')::jsonb)$$,'título liquidado aceita edição integral');
reset role;
select is((select count(*)::integer from private.finance_settlements where title_id='ab600000-0000-4000-8000-000000000001' and reversed_at is null),1,'uma nova baixa ativa');
select is((select principal_cents::text from private.finance_settlements where title_id='ab600000-0000-4000-8000-000000000001' and reversed_at is null),'4000','novo principal contabilizado');
select is((select fee_cents::text from private.finance_settlements where title_id='ab600000-0000-4000-8000-000000000001' and reversed_at is null),'80','taxa preservada');
select is((select interest_cents::text||','||fine_cents::text||','||discount_cents::text from private.finance_settlements where title_id='ab600000-0000-4000-8000-000000000001' and reversed_at is null),'100,50,25','juros multa desconto preservados');
select is((select sum(l.delta_cents)::text from public.church_ledger_lines l join private.finance_account_links a on a.ledger_id=l.account_id where a.catalog_id='df600000-0000-4000-8000-000000000001'),'4045','saldo corresponde ao novo líquido incluindo taxa');
select set_config('revision.unpaid',pg_temp.revision_payload('ab600000-0000-4000-8000-000000000001','ab610000-0000-4000-8000-000000000004','{"paid":""}')::text,true);
set local role authenticated;
select lives_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.unpaid')::jsonb)$$,'liquidado pode ser desmarcado');
reset role;
select is((select count(*)::integer from private.finance_settlements where title_id='ab600000-0000-4000-8000-000000000001' and reversed_at is null),0,'nenhuma baixa ativa após desmarcar');
select is((select sum(l.delta_cents)::text from public.church_ledger_lines l join private.finance_account_links a on a.ledger_id=l.account_id where a.catalog_id='df600000-0000-4000-8000-000000000001'),'0','baixa e taxa revertidas em conjunto');
select set_config('revision.invalid',pg_temp.revision_payload('ab600000-0000-4000-8000-000000000001','ab610000-0000-4000-8000-000000000005','{"kind":"expense","category":"df600000-0000-4000-8000-000000000002"}')::text,true);
set local role authenticated;
select throws_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.invalid')::jsonb)$$,'22023',null,'categoria incompatível recusada');
select throws_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,'cf600000-0000-4000-8000-000000000002',current_setting('revision.invalid')::jsonb)$$,'42501',null,'outra unidade não pode receber o lançamento');
reset role;
select set_config('revision.closed',pg_temp.revision_payload('ab600000-0000-4000-8000-000000000001','ab610000-0000-4000-8000-000000000006',jsonb_build_object('paid',current_date))::text,true);
select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.closed')::jsonb);
update public.church_ledger_periods set closed_through=current_date where unit_id=current_setting('f4.unit')::uuid;
select set_config('revision.closed_unpaid',pg_temp.revision_payload('ab600000-0000-4000-8000-000000000001','ab610000-0000-4000-8000-000000000007','{"paid":""}')::text,true);
set local role authenticated;
select throws_ok($$select public.finance_revise_entry(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,current_setting('revision.closed_unpaid')::jsonb)$$,'22023',null,'período fechado não permite desmarcar');
reset role;
select is((select status from private.finance_entries where id='ab600000-0000-4000-8000-000000000001'),'posted','erro mantém lançamento original');
select ok(not has_function_privilege('anon','public.finance_revise_entry(uuid,uuid,jsonb)','execute'),'visitante não edita');
select * from finish();
rollback;
